static bool glyph_dsc(const lv_font_t *font, lv_font_glyph_dsc_t *d, uint32_t code, uint32_t next) {
    (void)font; (void)next;
    for(size_t i=0;i<sizeof(glyphs)/sizeof(glyphs[0]);i++) {
        const Glyph *g=&glyphs[i]; if(g->code != code) continue;
        d->adv_w=g->adv; d->box_w=g->w; d->box_h=g->h; d->ofs_x=g->x; d->ofs_y=g->y;
        d->stride=g->w; d->format=LV_FONT_GLYPH_FORMAT_A8; d->gid.index=(uint32_t)i; return true;
    }
    return false;
}
static const void *glyph_bitmap(lv_font_glyph_dsc_t *d, lv_draw_buf_t *buf) {
    (void)buf; return glyphs[d->gid.index].data;
}
